async function db(env,stmts){
  const r=await fetch((env.TURSO_URL||'libsql://alqaqa-a-137-md.aws-sa-east-1.turso.io').replace('libsql://','https://')+'/v2/pipeline',{method:'POST',headers:{authorization:'Bearer '+env.TURSO_TOKEN,'content-type':'application/json'},
    body:JSON.stringify({requests:[...stmts.map(([q,a=[]])=>({type:'execute',stmt:{sql:q,args:a.map(val)}})),{type:'close'}]})});
  const d=await r.json();if(!r.ok)throw new Error('db');
  return d.results.slice(0,stmts.length).map(x=>{if(x.type==='error')throw new Error(x.error.message);const c=x.response.result;
    return c.rows.map(w=>Object.fromEntries(c.cols.map((k,i)=>[k.name,w[i].value==null?null:w[i].type==='integer'?+w[i].value:w[i].value])))});
}
