async function delMedia(env,u){const k=String(u||'').startsWith('/media/')?String(u).slice(7):null;if(k)await q1(env,'DELETE FROM media WHERE key=?',[k])}
async function media(req,env,url){
  const key=decodeURIComponent(url.pathname.slice(7));
  if(!/^[0-9a-f]{24}\.[a-z0-9]+$/.test(key))return new Response('Not found',{status:404});
  const m=(await q1(env,'SELECT size,ct FROM media WHERE key=? AND n=0',[key]))[0];
  if(!m)return new Response('Not found',{status:404});
  const size=m.size,win=/^image\//.test(m.ct)?7:2;let s=0,e=size-1,part=false;
  const rg=/^bytes=(\d*)-(\d*)$/.exec(req.headers.get('range')||'');
  if(rg&&(rg[1]!==''||rg[2]!=='')){if(rg[1]===''){s=Math.max(0,size-(+rg[2]))}else{s=+rg[1];if(rg[2]!=='')e=Math.min(+rg[2],size-1)}
    if(s>=size||s>e)return new Response(null,{status:416,headers:{'content-range':'bytes */'+size}});part=true}
  const cap=(Math.floor(s/CH)+win)*CH-1;if(e>cap){e=cap;part=true}
  const c0=Math.floor(s/CH),c1=Math.floor(e/CH);
  const rows=await q1(env,'SELECT n,data FROM media WHERE key=? AND n BETWEEN ? AND ? ORDER BY n',[key,c0,c1]);
  const out=new Uint8Array(e-s+1);
  for(const r of rows){const d=b64d(r.data),base=r.n*CH,a=Math.max(s,base),z=Math.min(e,base+d.length-1);if(z>=a)out.set(d.subarray(a-base,z-base+1),a-s)}
  const h=new Headers({'content-type':m.ct,'accept-ranges':'bytes','cache-control':'public, max-age=31536000, immutable'});
  if(part)h.set('content-range','bytes '+s+'-'+e+'/'+size);
  return new Response(out,{status:part?206:200,headers:h});
}
