async function newSession(env,u){const old=(await q1(env,'SELECT token FROM users WHERE id=?',[u.id]))[0];const t=old&&old.token?old.token:hex(24);if(!(old&&old.token))await q1(env,'UPDATE users SET token=? WHERE id=?',[t,u.id]);if(u.role==='user')await q1(env,"INSERT OR IGNORE INTO follows2(follower,followee,created) SELECT ?,id,? FROM users WHERE role='admin' LIMIT 1",[u.id,Date.now()]);return{token:t,user:{id:u.id,uid:u.uid,username:u.username,nick:u.nick,pic:pu(u.id,u.pic_v),role:u.role,bio:u.bio||'',priv:u.priv||0,verified:(+u.verified||0),toured:u.toured?1:0}}}
async function useCode(env,code,username,count){
  const r=await q1(env,'SELECT * FROM codes WHERE code=?',[code]);
  if(!r.length||!r[0].active||(!r[0].multi&&r[0].used_by))throw'كود التفعيل غير صحيح أو مستخدم';
  if(r[0].multi){if(count)await q1(env,'UPDATE codes SET uses=COALESCE(uses,0)+1 WHERE code=?',[code]);return 1}
  await q1(env,'UPDATE codes SET used_by=?,used_at=? WHERE code=?',[username,Date.now(),code]);
}
