let CFG=null,CFGT=0;
const cfgC=async env=>{if(CFG&&Date.now()-CFGT<60000)return CFG;CFG=await getCfg(env);CFGT=Date.now();return CFG};
const FC=new Map();
function fnv(t){let h=2166136261;for(let i=0;i<t.length;i++){h^=t.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(36)+t.length.toString(36)}
function staticRes(req,p){const f=FILES[p];if(!f)return null;let c=FC.get(p);
  if(!c){c={body:f[2]?Uint8Array.from(atob(f[0]),x=>x.charCodeAt(0)):f[0],et:'"'+fnv(f[0])+'"',ct:f[1]};FC.set(p,c)}
  const h={etag:c.et,'cache-control':/\.(png|svg|ico)$/.test(p)?'public, max-age=86400':'public, max-age=0, must-revalidate'};
  if(req.headers.get('if-none-match')===c.et)return new Response(null,{status:304,headers:h});
  h['content-type']=c.ct;return new Response(c.body,{headers:h})}
async function getCfg(env){const r=await q1(env,"SELECT k,v FROM settings WHERE k IN ('app_name','app_icon','app_terms','app_privacy')");const m=Object.fromEntries(r.map(x=>[x.k,x.v||'']));return{name:m.app_name||'',icon:m.app_icon||'',terms:m.app_terms||'',privacy:m.app_privacy||''}}
const REACTS=["👍", "❤️", "😂", "😮", "😢", "🙏", "🔥"];
async function reactMap(env,kind,ids,meId){const out={};ids=ids.map(x=>+x).filter(x=>x>0);if(!ids.length)return out;
  const rows=await q1(env,'SELECT msg_id,user_id,emoji FROM mreact WHERE kind=? AND msg_id IN ('+ids.join(',')+')',[kind]);
  for(const r of rows){const a=out[r.msg_id]||(out[r.msg_id]={});const o=a[r.emoji]||(a[r.emoji]={e:r.emoji,n:0,me:0});o.n++;if(r.user_id===meId)o.me=1}
  for(const k in out)out[k]=Object.values(out[k]);return out}
async function gRole(env,gid,uid){if(!(gid>0))return '';const r=(await q1(env,'SELECT role FROM chg_members WHERE gid=? AND user_id=?',[gid,uid]))[0];return r?r.role:''}
async function addable(env,me,ids){ids=ids.filter(x=>/^[0-9a-f]{16}$/.test(x));if(!ids.length)return [];const L=ids.map(x=>"'"+x+"'").join(',');
  const u=await q1(env,"SELECT id FROM users WHERE id IN ("+L+") AND role!='viewer' AND COALESCE(banned,0)=0");const ok=u.map(x=>x.id);if(me.role==='admin')return ok;
  const f=await q1(env,"SELECT follower,followee FROM follows2 WHERE (follower=?1 AND followee IN ("+L+")) OR (followee=?1 AND follower IN ("+L+"))",[me.id]);
  const s=new Set(f.map(x=>x.follower===me.id?x.followee:x.follower));
  const bk=await q1(env,"SELECT blocker,blocked FROM blocks WHERE (blocker=?1 AND blocked IN ("+L+")) OR (blocked=?1 AND blocker IN ("+L+"))",[me.id]);const bs=new Set(bk.map(x=>x.blocker===me.id?x.blocked:x.blocker));return ok.filter(x=>s.has(x)&&!bs.has(x))}
